    macro_indicator_us_unemployment: "US Unemployment Rate",
    macro_tip_cn_cpi_yoy: "Consumer Price Index YoY — measures consumer goods price changes. Moderate CPI (2-3%) supports earnings growth; high CPI triggers tightening expectations that compress valuations; deflation signals weak demand.",
    macro_tip_cn_ppi_yoy: "Producer Price Index YoY — factory-gate prices, leads CPI by 1-2 quarters. Rising PPI foreshadows cost pressure on downstream margins; falling PPI supports margin recovery for manufacturers.",
    macro_tip_cn_pmi: "Manufacturing PMI — 50 is the boom/bust line. Above 50 = expansion, below 50 = contraction. Sustained strength correlates with earnings improvement and cyclical opportunities; below 50 warns of slowdown risk.",
    macro_tip_cn_m2_yoy: "Broad Money Supply YoY — measures liquidity abundance. M2 growth above nominal GDP implies easing conditions favorable to risk assets; sustained M2 decline suggests tightening pressure on high-valuation sectors.",
    macro_tip_cn_new_credit: "New RMB Loans — credit injected into the real economy via banks. Expanding credit = easing cycle, beneficial to rate-sensitive sectors like finance and property; contracting credit is a bearish signal.",
    macro_tip_cn_social_financing: "Total Social Financing Stock — all funding the real economy receives from the financial system. Rising TSF growth is a leading indicator of economic stabilization; declining growth signals a weakening credit cycle.",
    macro_tip_cn_10y_yield: "10Y Government Bond Yield — risk-free rate anchor. Falling yields = bond bull + DCF valuation boost for growth stocks; rapidly rising yields compresses high-valuation sectors and may trigger capital outflow from EM.",
    macro_tip_cn_lpr_1y: "1Y LPR — short-term lending benchmark rate. LPR cuts directly reduce corporate financing costs, stimulating investment and consumption; hikes tighten liquidity expectations.",
    macro_tip_cn_lpr_5y: "5Y LPR — mortgage and long-term loan benchmark. 5Y LPR cuts directly impact property and infrastructure sectors; key window for observing monetary policy stance.",
    macro_tip_cn_margin_sh: "SSE Margin Balance — A-share leverage sentiment. Rising margin balance = rising risk appetite, often accompanied by volume-price gains; rapid decline warns of pullback or stampede risk.",
    macro_tip_cn_margin_sz: "SZSE Margin Balance — same as SSE but focused on mid/small-cap / tech growth leverage sentiment. SZSE margin changes have strong leading power for ChiNext index.",
    macro_tip_us_cpi_yoy: "US CPI YoY — global inflation barometer. US CPI beat → Fed hawkish hike → strong dollar → EM capital outflow + Treasury yield rise → global risk assets under pressure.",
    macro_tip_us_10y_yield: "US 10Y Treasury Yield — global asset pricing anchor. Rising yields suppress global growth stock valuations, especially Nasdaq and HK tech stocks; falling yields release valuation room.",
    macro_tip_us_core_cpi_mom: "US Core CPI MoM — inflation excluding food & energy. Core CPI is one of the Fed's most important decision references; MoM beats strengthen rate-hike path expectations.",
    macro_tip_us_ppi: "US PPI YoY — production-side inflation metric. PPI transmits to CPI in ~3-6 months, useful for forecasting future inflation trajectory. Surging PPI raises stagflation concerns.",
    macro_tip_us_industrial_production: "Industrial Production YoY — US manufacturing health gauge. Strong output = healthy fundamentals supporting S&P earnings expectations; sharp decline signals recession risk, favors defensive sectors.",
    macro_tip_us_non_farm: "Nonfarm Payrolls — among the most important monthly data points. NFP beat → hot labor market → wage inflation → sticky inflation → Fed keeps rates higher for longer.",
    macro_tip_us_unemployment: "Unemployment Rate — inverse signal: low UR = tight labor market = wage-inflation pressure. Below 4% makes it hard for Fed to cut; above 4.5% significantly raises recession probability.",
    macro_bench_cn_cpi_yoy: "Target range 2%–3%",
    macro_bench_cn_ppi_yoy: "Normal range 0%–3%",
